function randomInt(bound){const range=4294967296,limit=range-range%bound;let n;do{const v=new Uint32Array(1);crypto.getRandomValues(v);n=v[0];}while(n>=limit);return n%bound;}
function shuffled(){const a=Array.from({length:all.length},(_,i)=>i);for(let i=a.length-1;i>0;i--){const j=randomInt(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;}
function valid(s){return s&&s.version===1&&s.size===all.length&&Array.isArray(s.remaining)&&new Set(s.remaining).size===s.remaining.length&&s.remaining.every(i=>Number.isInteger(i)&&i>=0&&i<all.length)&&Array.isArray(s.recent)&&s.recent.length<=8&&s.recent.every(i=>Number.isInteger(i)&&i>=0&&i<all.length);}
function load(){if(memory)return memory;try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(valid(saved))return memory=saved;}catch{}return memory={version:1,size:all.length,remaining:[],recent:[]};}
function next(){const s=load();if(!s.remaining.length)s.remaining=shuffled();let p=s.remaining.findIndex(i=>!s.recent.includes(i));if(p<0)p=0;const index=s.remaining.splice(p,1)[0];s.recent.push(index);s.recent=s.recent.slice(-8);try{localStorage.setItem(key,JSON.stringify(s));}catch{}return {index,lot:all[index]};}
